import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.jit
def _relu_kernel(x_ptr, out_ptr, n_elements, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n_elements
    x = tl.load(x_ptr + offs, mask=mask)
    y = tl.maximum(x, 0.0)
    tl.store(out_ptr + offs, y, mask=mask)


def _triton_relu(x):
    x = x.contiguous()
    out = torch.empty_like(x)
    n_elements = x.numel()
    BLOCK = 1024
    grid = (triton.cdiv(n_elements, BLOCK),)
    _relu_kernel[grid](x, out, n_elements, BLOCK=BLOCK)
    return out


class _TritonReLU(nn.Module):
    def forward(self, x):
        return _triton_relu(x)


class ModelNew(nn.Module):
    def __init__(self, input_size, hidden_layer_sizes, output_size):
        super(ModelNew, self).__init__()

        layers = []
        current_input_size = input_size

        for index, hidden_size in enumerate(hidden_layer_sizes):
            layers.append(nn.Linear(current_input_size, hidden_size))
            if index == len(hidden_layer_sizes) - 1:
                layers.append(_TritonReLU())
            else:
                layers.append(nn.ReLU())
            current_input_size = hidden_size

        layers.append(nn.Linear(current_input_size, output_size))
        self.network = nn.Sequential(*layers)

    def forward(self, x):
        return self.network(x)

