import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.jit
def _relu_kernel(
    x_ptr,
    out_ptr,
    n_elements,
    BLOCK: tl.constexpr,
):
    block_start = tl.program_id(0) * BLOCK
    offsets = block_start + tl.arange(0, BLOCK)
    mask = offsets < n_elements

    x = tl.load(x_ptr + offsets, mask=mask)
    y = tl.maximum(x, 0.0)
    tl.store(out_ptr + offsets, y, mask=mask)


def _triton_relu(x):
    x = x.contiguous()
    out = torch.empty_like(x)
    n_elements = x.numel()

    if n_elements == 0:
        return out

    block = 512
    grid = (triton.cdiv(n_elements, block),)
    _relu_kernel[grid](
        x,
        out,
        n_elements,
        BLOCK=block,
        num_warps=4,
        num_stages=1,
    )
    return out


class _TritonReLU(nn.Module):
    def forward(self, x):
        return _triton_relu(x)


